mapper.select:
select e.id, e.exam_name, e.status, e.duration, e.start_time, e.paper_id, es.status as studentExamStatus from exam e INNER JOIN exam_student es ON es.exam_id = e.id AND es.student_id = #{stuId}
${ew.customSqlSegment} AND e.status != 0 AND e.deleted = 0
AND e.status = 1 AND #{now} < e.start_time
AND e.status = 1 AND #{now} >= e.start_time AND #{now} <= DATE_ADD(e.start_time, INTERVAL e.duration MINUTE)
AND e.status = 1 AND #{now} > DATE_ADD(e.start_time, INTERVAL e.duration MINUTE)
AND e.status = #{viewStatus.code}
